internal val HADITHS: List<HadithItem> = listOf(
    HadithItem("hadith-niyyah", "সহীহুল বুখারী", 1, "ওহীর সূচনা অধ্যায়", "আমীরুল মুমিনীন হযরত উমর ইবনুল খাত্তাব (রা.) থেকে বর্ণিত", "إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى دُنْيَا يُصِيبُهَا أَوْ إِلَى امْرَأَةٍ يَنْكِحُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ", "নিশ্চয়ই সমস্ত কাজ নিয়তের ওপর নির্ভরশীল। আর প্রত্যেক ব্যক্তি যা নিয়ত করে কেবল তা-ই পায়। সুতরাং যার হিজরত দুনিয়া হাসিলের উদ্দেশ্যে কিংবা কোনো নারীকে বিয়ের উদ্দেশ্যে হবে, তার হিজরত সেই উদ্দেশ্যেই গণ্য হবে যার জন্য সে হিজরত করেছে।", "মুত্তাফাক্ব আলাইহি (সহীহ বুখারী ও মুসলিম)", "ইমাম শাফেয়ী (রহ.) বলেছেন: এই হাদিসটি দ্বীনের এক-তৃতীয়াংশ জ্ঞানের সমকক্ষ। প্রতিটি নেক আমলের পুরস্কার প্রাপ্তি শুধুমাত্র আল্লাহর সন্তুষ্টির উদ্দেশ্যে নিয়ত করার ওপর নির্ভরশীল। লোক দেখানো বা দুনিয়াবি উদ্দেশ্যে কৃত কোনো আমল আল্লাহর দরবারে গ্রহণযোগ্য নয়।", "INTENTION_FAITH", true, 1, "সহীহুল বুখারী: 1"),
    HadithItem("hadith-jibreel", "সহীহ মুসলিম", 8, "কিতাবুল ঈমান", "হযরত উমর ইবনুল খাত্তাব (রা.) থেকে বর্ণিত", "قَالَ: فَأَخْبِرْنِي عَنِ الإِحْسَانِ، قَالَ: «أَنْ تَعْبُدَ اللهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ»", "জিবরীল (আ.) বললেন: আমাকে ইহসান সম্পর্কে বলুন। রাসূলুল্লাহ ﷺ বললেন: \"ইহসান হলো—তুমি এমনভাবে আল্লাহর ইবাদত করবে যেন তুমি তাঁকে দেখছো; আর যদি তুমি তাঁকে দেখতে নাও পাও, তবে নিশ্চয় তিনি তোমাকে দেখছেন।\"", "সহীহ (সহীহ মুসলিম)", "ইহসান হলো ইবাদতের সর্বোচ্চ পর্যায়। মুমিন যখন বিশ্বাস করে যে আল্লাহ সর্বক্ষণ তাকে নিরীক্ষণ করছেন (মুরাকাবা), তখন তার নামাজ ও আচার-আচরণে সর্বোচ্চ বিনয় ও নিষ্ঠা ফুটে ওঠে।", "INTENTION_FAITH", true, 2, "সহীহ মুসলিম: 8"),
    HadithItem("hadith-brotherhood-love", "সহীহুল বুখারী", 13, "কিতাবুল ঈমান", "হযরত আনাস ইবনে মালিক (রা.) থেকে বর্ণিত", "لاَ يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ", "তোমাদের কেউ ততক্ষণ পর্যন্ত প্রকৃত মুমিন হতে পারবে না, যতক্ষণ না সে নিজের ভাইয়ের জন্য তা-ই পছন্দ করবে যা সে নিজের জন্য পছন্দ করে।", "মুত্তাফাক্ব আলাইহি (সহীহ বুখারী ও মুসলিম)", "ঈমানের পরিপূর্ণতা আসে অন্তরের পরশ্রীকাতরতা (হিংসা) দূর করে অন্যের জন্য কল্যাণ কামনার মাধ্যমে। একজন মুমিন তার মুসলিম ভাইয়ের সুখ, শান্তি ও কল্যাণে ঠিক তেমনি আনন্দিত হয় যেমনটা সে নিজের বেলায় পছন্দ করে।", "BROTHERHOOD_SERVICE", true, 13, "সহীহুল বুখারী: 13"),
    HadithItem("hadith-good-character-scale", "জামে আত-তিরমিযী", 2002, "সদাচার ও অনুগ্রহ অধ্যায়", "হযরত আবু দারদা (রা.) থেকে বর্ণিত", "مَا مِنْ شَيْءٍ أَثْقَلُ فِي مِيزَانِ الْمُؤْمِنِ يَوْمَ الْقِيَامَةِ مِنْ حُسْنِ الْخُلُقِ، وَإِنَّ اللَّهَ لَيُبْغِضُ الْفَاحِشَ الْبَذِيءَ", "কিয়ামতের দিন মুমিনের দাঁড়িপাল্লায় উত্তম চরিত্রের চেয়ে ভারী আর কোনো জিনিস হবে না। আর নিশ্চয়ই আল্লাহ তাআলা অশ্লীল ও কটুভাষীকে চরম ঘৃণা করেন।", "সহীহ (সহীহ আত-তিরমিযী)", "এই হাদিসে কিয়ামতের মিজানে উত্তম চরিত্রের বিশেষ মর্যাদা এবং অশ্লীল ও কটুভাষী হওয়ার নিন্দা বর্ণিত হয়েছে।", "CHARACTER_MANNERS", false, null, "জামে আত-তিরমিযী: 2002"),
    HadithItem("hadith-anger-control", "সহীহুল বুখারী", 6114, "আদব ও শিষ্টাচার অধ্যায়", "হযরত আবু হুরায়রা (রা.) থেকে বর্ণিত", "لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ، إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ", "কুস্তিতে যে অপরকে ধরাশায়ী করে সে প্রকৃত বীর নয়; বরং প্রকৃতপক্ষে শক্তিশালী সেই ব্যক্তি, যে রাগের সময় নিজেকে নিয়ন্ত্রণে রাখতে পারে।", "মুত্তাফাক্ব আলাইহি (সহীহ বুখারী ও মুসলিম)", "শারীরিক শক্তির চেয়ে আত্মিক ও মানসিক নিয়ন্ত্রণ বেশি কঠিন। ক্রোধ শয়তানের প্ররোচনায় আসে। রাগের মুহূর্তে চুপ থাকা, অজু করা বা অবস্থান পরিবর্তন করা সুন্নাত।", "CHARACTER_MANNERS", true, 16, "সহীহুল বুখারী: 6114"),
    HadithItem("hadith-seeking-knowledge", "সহীহ মুসলিম", 2699, "যিকির, দোয়া ও তওবা অধ্যায়", "হযরত আবু হুরায়রা (রা.) থেকে বর্ণিত", "مَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا، سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ", "যে ব্যক্তি দ্বীনি জ্ঞানার্জনের জন্য কোনো পথ অবলম্বন করে, আল্লাহ তাআলা তার কারণে জান্নাতের পথ তার জন্য সহজ করে দেন।", "সহীহ (সহীহ মুসলিম)", "এই হাদিসে জ্ঞান অন্বেষণের পথে চলার জন্য জান্নাতের পথ সহজ হওয়ার সুসংবাদ দেওয়া হয়েছে।", "KNOWLEDGE_SEEKING", true, 36, "সহীহ মুসলিম: 2699"),
    HadithItem("hadith-learn-teach-quran", "সহীহুল বুখারী", 5027, "কুরআনের ফজিলত অধ্যায়", "হযরত উসমান ইবনে আফফান (রা.) থেকে বর্ণিত", "خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ", "তোমাদের মধ্যে সর্বোত্তম ব্যক্তি সেই, যে নিজে কুরআন শেখে এবং অন্যকে তা শেখায়।", "সহীহ (সহীহ বুখারী)", "আল্লাহর কালাম শিক্ষা করা এবং তা অপরকে শিক্ষা দেওয়া উম্মতের মধ্যে সর্বোচ্চ মর্যাদাপূর্ণ আমল। এটি একটি অফুরন্ত সদকায়ে জারিয়ার উৎস।", "KNOWLEDGE_SEEKING", false, null, "সহীহুল বুখারী: 5027"),
    HadithItem("hadith-tawbah-joy", "সহীহ মুসলিম", 2747, "তওবার অধ্যায়", "হযরত আনাস ইবনে মালিক (রা.) থেকে বর্ণিত", "لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ حِينَ يَتُوبُ إِلَيْهِ، مِنْ أَحَدِكُمْ كَانَ عَلَى رَاحِلَتِهِ بِأَرْضِ فَلاَةٍ، فَانْفَلَتَتْ مِنْهُ وَعَلَيْهَا طَعَامُهُ وَشَرَابُهُ", "বান্দা যখন আল্লাহর কাছে তওবা করে, তখন আল্লাহ তাআলা সেই ব্যক্তির চেয়েও বেশি আনন্দিত হন, যে কোনো জনমানবহীন মরুভূমিতে খাদ্য ও পানীয়সহ বাহন হারিয়ে ফেলার পর নিরাশ হয়ে মরার জন্য শুয়ে পড়েছিল, অতঃপর হঠাৎ চোখ মেলে তার বাহনটি তার সামনে অক্ষত দেখতে পায়!", "মুত্তাফাক্ব আলাইহি (সহীহ বুখারী ও মুসলিম)", "এই হাদিসে বান্দার তওবার প্রতি আল্লাহর আনন্দের বিষয়টি একটি শক্তিশালী উপমার মাধ্যমে বর্ণিত হয়েছে; তাই গুনাহের পর তওবা করে আল্লাহর দিকে ফিরে আসার উৎসাহ পাওয়া যায়।", "REPENTANCE_MERCY", false, null, "সহীহ মুসলিম: 2747"),
    HadithItem("hadith-adam-children-err", "জামে আত-তিরমিযী", 2499, "কিয়ামতের বিবরণ অধ্যায়", "হযরত আনাস ইবনে মালিক (রা.) থেকে বর্ণিত", "كُلُّ ابْنِ آدَمَ خَطَّاءٌ، وَخَيْرُ الْخَطَّائِينَ التَّوَّابُونَ", "আদম সন্তানের প্রত্যেকেই ভুলকারী বা অপরাধী; আর ভুলকারীদের মধ্যে সর্বোত্তম হলো তারা, যারা তওবা করে ফিরে আসে।", "হাসান (সুনানে আত-তিরমিযী ও ইবনে মাজাহ)", "মানুষ ভুলের ঊর্ধ্বে নয়। তবে প্রকৃত মুমিনের বৈশিষ্ট্য হলো ভুলের পর দম্ভ না দেখিয়ে অবিলম্বে অনুতপ্ত হওয়া এবং আল্লাহর দরবারে ক্ষমা প্রার্থনা করা।", "REPENTANCE_MERCY", false, null, "জামে আত-তিরমিযী: 2499"),
    HadithItem("hadith-parents-mother", "সহীহুল বুখারী", 5971, "আদব ও সদাচার অধ্যায়", "হযরত আবু হুরায়রা (রা.) থেকে বর্ণিত", "جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ﷺ فَقَالَ: يَا رَسُولَ اللَّهِ، مَنْ أَحَقُّ النَّاسِ بِحُسْنِ صَحَابَتِي؟ قَالَ: «أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أَبُوكَ»", "এক ব্যক্তি রাসূলুল্লাহ ﷺ-এর কাছে এসে জিজ্ঞেস করল: \"হে আল্লাহর রাসূল! আমার সর্বোত্তম সদাচরণ পাওয়ার সবচেয়ে বেশি হকদার কে?\" তিনি বললেন: \"তোমার মা।\" লোকটি বলল: \"তারপর কে?\" তিনি বললেন: \"তোমার মা।\" লোকটি বলল: \"তারপর কে?\" তিনি বললেন: \"তোমার মা।\" লোকটি বলল: \"তারপর কে?\" তিনি বললেন: \"তারপর তোমার বাবা।\"", "মুত্তাফাক্ব আলাইহি (সহীহ বুখারী ও মুসলিম)", "এই হাদিসে উত্তম সাহচর্য ও সদাচরণের অধিকারের ক্ষেত্রে মাকে তিনবার এবং এরপর বাবাকে উল্লেখ করা হয়েছে। এতে মায়ের বিশেষ অধিকারের বিষয়টি স্পষ্ট হয়।", "PARENTS_FAMILY", false, null, "সহীহুল বুখারী: 5971"),
    HadithItem("hadith-silatur-rahim-rizq", "সহীহুল বুখারী", 2067, "ক্রয়-বিক্রয় অধ্যায়", "হযরত আনাস ইবনে মালিক (রা.) থেকে বর্ণিত", "مَنْ أَحَبَّ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ، وَيُنْسَأَ لَهُ فِي أَثَرِهِ، فَلْيَصِلْ رَحِمَهُ", "যে ব্যক্তি তার রিজিকে প্রাচুর্য ও বরকত পেতে চায় এবং তার হায়াত দীর্ঘ হোক তা পছন্দ করে, সে যেন আত্মীয়তার বন্ধন অটুট রাখে (সিলাতুর রাহিম)।", "মুত্তাফাক্ব আলাইহি (সহীহ বুখারী ও মুসলিম)", "আত্মীয়দের সাথে যোগাযোগ রাখা, তাদের সুখে-দুঃখে পাশে থাকা বরকতময় রিজিক ও জীবনে বরকত লাভের প্রমাণিত আমল। পক্ষান্তরে আত্মীয়তার সম্পর্ক ছিন্নকারী জান্নাতে প্রবেশ করতে পারবে না।", "PARENTS_FAMILY", false, null, "সহীহুল বুখারী: 2067"),
    HadithItem("hadith-honest-merchant", "জামে আত-তিরমিযী", 1209, "ব্যবসা-বাণিজ্য অধ্যায়", "হযরত আবু সাঈদ আল-খুদরী (রা.) থেকে বর্ণিত", "التَّاجِرُ الصَّدُوقُ الأَمِينُ مَعَ النَّبِيِّينَ، وَالصِّدِّيقِينَ، وَالشُّهَدَاءِ", "সত্যবাদী ও বিশ্বস্ত আমানতদার ব্যবসায়ী কিয়ামতের দিন নবীগণ, সিদ্দীকগণ এবং শহীদগণের সাথে থাকবেন।", "হাসান (সুনানে আত-তিরমিযী: ১২০৯)", "ব্যবসায়ে ওজনে কম না দেওয়া, ভেজাল মিশ্রণ না করা এবং মিথ্যার আশ্রয় না নিয়ে সততা বজায় রাখলে ব্যবসায়ী পরকালে আম্বিয়া ও শহীদগণের সম্মানজনক মর্যাদা লাভ করবেন।", "HALAL_LIVELIHOOD", false, null, "জামে আত-তিরমিযী: 1209"),
    HadithItem("hadith-halal-haram-clear", "সহীহুল বুখারী", 52, "কিতাবুল ঈমান", "হযরত নুমান ইবনে বাশীর (রা.) থেকে বর্ণিত", "إِنَّ الحَلاَلَ بَيِّنٌ، وَإِنَّ الحَرَامَ بَيِّنٌ، وَبَيْنَهُمَا مُشْتَبِهَاتٌ لاَ يَعْلَمُهُنَّ كَثِيرٌ مِنَ النَّاسِ، فَمَنِ اتَّقَى الشُّبُهَاتِ اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ... أَلاَ وَإِنَّ فِي الجَسَدِ مُضْغَةً، إِذَا صَلَحَتْ صَلَحَ الجَسَدُ كُلُّهُ، وَإِذَا فَسَدَتْ فَسَدَ الجَسَدُ كُلُّهُ، أَلاَ وَهِيَ القَلْبُ", "নিশ্চয়ই হালাল স্পষ্ট এবং হারামও স্পষ্ট। আর এ দুটির মাঝে রয়েছে বহু সন্দেহজনক বিষয়, যা অনেক মানুষ জানে না। যে ব্যক্তি সন্দেহজনক বিষয় থেকে বেঁচে থাকল, সে নিজের দ্বীন ও আত্মসম্মানকে নিষ্কলুষ রাখল... জেনে রেখো! শরীরের মধ্যে একটি গোশতের টুকরো রয়েছে; তা যদি সুস্থ ও ভালো থাকে তবে পুরো শরীরটাই ভালো থাকে, আর তা যদি নষ্ট হয়ে যায় তবে পুরো শরীরটাই নষ্ট হয়ে যায়। জেনে রেখো! সেই টুকরোটি হলো কলব (অন্তর)।", "মুত্তাফাক্ব আলাইহি (সহীহ বুখারী ও মুসলিম)", "দ্বীনের প্রতিটি বিষয়ে সন্দেহপূর্ণ দিক পরিহার করা তাকওয়ার পরিচায়ক। মানুষের বাহ্যিক আমলের শুদ্ধতা নির্ভর করে কলবের ঈমানি সুস্থতা ও পরিচ্ছন্নতার ওপর।", "HALAL_LIVELIHOOD", true, 6, "সহীহুল বুখারী: 52"),
    HadithItem("hadith-relieving-distress", "সহীহ মুসলিম", 2699, "যিকির ও দোয়া অধ্যায়", "হযরত আবু হুরায়রা (রা.) থেকে বর্ণিত", "مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا، نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ، يَسَّرَ اللَّهُ عَلَيْهِ فِي الدُّنْيَا وَالآخِرَةِ، وَمَنْ سَتَرَ مُسْلِمًا، سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالآخِرَةِ، وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ", "যে ব্যক্তি কোনো মুমিনের পার্থিব কোনো কষ্ট লাঘব করে দেবে, আল্লাহ কিয়ামতের দিন তার একটি বড় বিপদ দূর করে দেবেন। যে ব্যক্তি কোনো অভাবগ্রস্তের সংকট সহজ করবে, আল্লাহ দুনিয়া ও আখিরাতে তার সবকিছু সহজ করে দেবেন। আর যে ব্যক্তি কোনো মুসলিমের দোষত্রুটি ঢেকে রাখবে, আল্লাহ দুনিয়া ও আখিরাতে তার দোষত্রুটি গোপন রাখবেন। বান্দা যতক্ষণ পর্যন্ত তার ভাইয়ের সাহায্যে নিয়োজিত থাকে, আল্লাহ ততক্ষণ পর্যন্ত সেই বান্দার সাহায্যে থাকেন।", "সহীহ (সহীহ মুসলিম)", "অন্যের সেবা ও বিপদগ্রস্ত মানুষের পাশে দাঁড়ানো আল্লাহর সাহায্য পাওয়ার সবচেয়ে সহজ ও পরীক্ষিত মাধ্যম। কারো গোপনীয় দোষ সমাজে প্রচার না করে গোপন রাখা মহান চারিত্রিক বৈশিষ্ট্য।", "BROTHERHOOD_SERVICE", true, 36, "সহীহ মুসলিম: 2699"),
    HadithItem("hadith-leaving-useless", "জামে আত-তিরমিযী", 2317, "যুহদ (অনাসক্তি) অধ্যায়", "হযরত আবু হুরায়রা (রা.) থেকে বর্ণিত", "مِنْ حُسْنِ إِسْلاَمِ المَرْءِ تَرْكُهُ مَا لاَ يَعْنِيهِ", "মানুষের ইসলামের অন্যতম সৌন্দর্য হলো—তার জন্য যা অনর্থক ও অপ্রয়োজনীয় (যার সাথে দ্বীন বা দুনিয়ার কোনো কল্যাণ নেই), তা বর্জন করা।", "হাসান (সুনানে আত-তিরমিযী: ২৩১৭)", "অনর্থক তর্ক, পরনিন্দা, অন্যের ব্যক্তিগত ব্যাপারে নাক গলানো কিংবা সময়ের অপচয়কারী কাজ পরিহার করাই একজন প্রজ্ঞাবান ও নিষ্ঠাবান মুসলিমের প্রকৃত রূপ।", "CHARACTER_MANNERS", true, 12, "জামে আত-তিরমিযী: 2317"),
    HadithItem("hadith-smiling-charity", "জামে আত-তিরমিযী", 1956, "সদাচার অধ্যায়", "হযরত আবু যর আল-গিফারী (রা.) থেকে বর্ণিত", "تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ لَكَ صَدَقَةٌ", "তোমার মুসলিম ভাইয়ের মুখের দিকে তাকিয়ে তোমার একটু মুচকি হাসি দেওয়াও একটি সদকা (পুণ্যের কাজ)।", "হাসান গরীব (জামে আত-তিরমিযী: ১৯৫৬)", "সদকা কেবল অর্থ দিয়েই হয় না। সহাস্য বদন, মধুর ব্যবহার ও মানুষের মুখে হাসি ফোটানোও সদকার সমতুল্য সাওয়াবের অধিকারী করে।", "BROTHERHOOD_SERVICE", false, null, "জামে আত-তিরমিযী: 1956")
)
